{
  "aggregate_id": "DEF-NRS-484A-130::motor_vehicle",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract describes a human-powered device, which the vehicle definition expressly excepts."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "The contract describes a motor vehicle, satisfying the admitting requirement of self-propulsion without rail operation."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than a transport device, so the admitting words reach no member."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "Commercial mass or licensing does not establish self-propulsion, so the admitting words do not decide the class."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "underdetermined",
      "reason": "An assisting electric motor and a jurisdiction-labelled class attribute do not themselves establish the equipment, power and assistance-speed requirements of the defined electric-bicycle exception."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "underdetermined",
      "reason": "The contract does not impose the statutory weight and motor-only speed limits, so the electric-scooter exception does not establish exclusion of the entire class."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation does not establish self-propulsion, leaving the class undecided by the admitting words."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "A fire-fighting purpose does not establish that the vehicle is self-propelled, so the words do not decide the class."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The jurisdiction-classed moped is a vehicle propelled by its own engine or motor, and its definition expressly distinguishes it from excluded electric bicycles and electric scooters."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The contract expressly supplies self-propulsion and excludes rail vehicles and separately classed powered two-wheelers."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The contract describes a motor vehicle, supplying the self-propelled, nonrail character required by the admitting words."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official or contracted road service does not establish self-propulsion, so the definition does not decide the class."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person rather than the device transporting that person, so the vehicle-admitting words reach no member."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person, not a transport device admitted by the vehicle definition."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The contract describes on-track equipment, which the express restriction against operation upon rails excludes."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "The contract describes a bus, whose motor-vehicle character supplies the required self-propulsion and absence of rail operation."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "A passenger vehicle's hire status and markings do not establish self-propulsion, leaving the class undecided."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "Although the bus branch supplies motor-vehicle character, the lengthened passenger-vehicle branch does not establish self-propulsion for every member."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "The contract encompasses drawn vehicles and combinations without establishing that every member is itself self-propelled."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "The contract describes a bus, whose motor-vehicle character satisfies the self-propelled, nonrail admitting clause."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "The contract expressly describes a motor vehicle, satisfying the self-propelled, nonrail admitting clause."
    }
  ]
}

